def render_dashboard():
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jane Verify</title><style>\n:root{--bg:#000;--panel:#080b12;--line:#1d2a3d;--navy:#163c78;--text:#f5f7fb;--muted:#9aa5b3;--ok:#5cdb95;--warn:#f1c75b;--bad:#ff7171}*{box-sizing:border-box}body{margin:0;background:#000;color:var(--text);font-family:Segoe UI,Arial,sans-serif}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.side{border-right:1px solid var(--line);padding:26px 18px}.brand{font-size:29px;font-weight:800}.brand span{color:#7ab0ff}.nav{margin-top:30px;display:grid;gap:8px;color:var(--muted)}.nav b{color:white;background:#0d1c32;border:1px solid #234678;padding:10px;border-radius:8px}main{padding:32px;max-width:1450px}.eyebrow{color:#7ab0ff;text-transform:uppercase;letter-spacing:.15em;font-size:11px}.toolbar,.panel{border:1px solid var(--line);background:linear-gradient(#0b1019,#05070b);border-radius:14px;padding:16px;margin-top:16px}.toolbar{display:grid;grid-template-columns:1fr 160px auto auto;gap:10px}.toolbar input,.toolbar select{background:#020306;color:white;border:1px solid #2b3b54;padding:12px;border-radius:8px}button{background:linear-gradient(#2157a0,#123467);color:white;border:1px solid #3972b7;border-radius:8px;padding:11px 16px;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.metric{font-size:30px;font-weight:800}.muted{color:var(--muted)}pre{white-space:pre-wrap;background:#020306;border:1px solid #172235;padding:12px;border-radius:8px;max-height:320px;overflow:auto}.finding{border-left:3px solid var(--warn);padding:8px 10px;margin:8px 0;background:#080b11}.bad{color:var(--bad)}.ok{color:var(--ok)}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{display:none}.toolbar,.grid{grid-template-columns:1fr}}\n</style></head><body><div class="shell"><aside class="side"><div class="brand">Jane <span>Verify</span></div><div class="muted">Software Validation Platform</div><div class="nav"><b>Validate</b><div>Testing</div><div>Inspection</div><div>Documentation</div><div>Reports</div><div>History</div></div></aside><main><div class="eyebrow">Runs on JaneOS · managed by Jane</div><h1>Is this software ready?</h1><p class="muted">Deterministic validation, sandboxed test execution, code/security inspection and generated documentation.</p><div class="toolbar"><input id="root" placeholder="Project path"><select id="trust"><option value="trusted">Trusted project</option><option value="untrusted">Untrusted / sandboxed</option></select><button onclick="authorizeProject()">Authorize</button><button onclick="validateProject()">Validate</button></div><div class="grid"><div class="panel"><div class="muted">Evidence score</div><div class="metric" id="score">—</div></div><div class="panel"><div class="muted">Validation</div><div class="metric" id="status">—</div></div><div class="panel"><div class="muted">Findings</div><div class="metric" id="findings">—</div></div></div><div class="panel"><h3>Stack</h3><div id="stack" class="muted">No project validated.</div></div><div class="panel"><h3>Checks</h3><div id="checks"></div></div><div class="panel"><h3>Code & Security Inspection</h3><div id="findingList"></div></div><div class="panel"><h3>Generated artifacts</h3><pre id="artifacts">—</pre></div></main></div><script>\nasync function authorizeProject(){let root=document.getElementById(\'root\').value;let r=await fetch(\'/api/projects/authorize\',{method:\'POST\',headers:{\'content-type\':\'application/json\'},body:JSON.stringify({root})});alert(r.ok?\'Project authorized\':await r.text())}\nasync function validateProject(){let root=document.getElementById(\'root\').value,trust=document.getElementById(\'trust\').value;let r=await fetch(\'/api/validate\',{method:\'POST\',headers:{\'content-type\':\'application/json\'},body:JSON.stringify({root,trust})});if(!r.ok){alert(await r.text());return}let d=await r.json(),v=d.validation;document.getElementById(\'score\').textContent=v.score+\'/100\';let st=document.getElementById(\'status\');st.textContent=v.status.toUpperCase();st.className=\'metric \'+(v.status===\'pass\'?\'ok\':v.status===\'fail\'?\'bad\':\'\');document.getElementById(\'findings\').textContent=d.findings.length;document.getElementById(\'stack\').textContent=[...v.stack.languages,...v.stack.frameworks,...v.stack.test_frameworks].join(\' · \');document.getElementById(\'checks\').innerHTML=v.checks.map(c=>`<div class="finding"><b>${c.status.toUpperCase()}</b> ${c.name} <span class="muted">${c.category}</span><div class="muted">${c.reason||\'\'}</div></div>`).join(\'\');document.getElementById(\'findingList\').innerHTML=d.findings.slice(0,100).map(f=>`<div class="finding"><b>${f.severity.toUpperCase()}</b> ${f.message}<div class="muted">${f.file}:${f.line}</div></div>`).join(\'\')||\'<div class="muted">No heuristic findings.</div>\';document.getElementById(\'artifacts\').textContent=JSON.stringify(d.artifacts,null,2)}\n</script></body></html>'
